/**
 * Turns a repository `Page` into what the pagination UI needs. Repositories
 * return cursor pages; the UI wants page counts and a "there is more" cursor,
 * and this module is the translation between the two.
 */
import { DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE } from "@/config/constants";
import type { Page } from "@/types/common";
import { makePage } from "@/types/common";

/** Number of pages a total spans; always at least 1 so the UI can render "1 of 1". */
export function pageCount(total: number, perPage: number): number {
  const size = clampPageSize(perPage);
  if (total <= 0) return 1;
  return Math.ceil(total / size);
}

/** Clamps a caller-supplied page size into the range the schemas allow. */
export function clampPageSize(perPage: number): number {
  if (!Number.isFinite(perPage) || perPage <= 0) return DEFAULT_PAGE_SIZE;
  return Math.min(Math.floor(perPage), MAX_PAGE_SIZE);
}

export function emptyPage<T>(): Page<T> {
  return makePage<T>([], null, 0);
}

/**
 * Trims an over-fetched row set to one page. Repositories query `limit + 1`
 * rows; if the extra row came back there is a next page, and its cursor is
 * the last kept row's cursor.
 */
export function sliceToPage<T>(
  items: readonly T[],
  limit: number,
  total: number,
  cursorOf: (item: T) => string,
): Page<T> {
  const size = clampPageSize(limit);
  const hasMore = items.length > size;
  const kept = hasMore ? items.slice(0, size) : items.slice();
  const last = kept[kept.length - 1];
  return makePage(kept, hasMore && last !== undefined ? cursorOf(last) : null, total);
}
import { z } from "zod";

/**
 * Coercions for reading pagination out of `searchParams`. Remember that in
 * Next 16 `searchParams` is a Promise — `await` it before parsing.
 */
export const searchParamsPaginationSchema = z.object({
  page: z.coerce.number().int().min(1).catch(1),
  perPage: z.coerce.number().int().min(1).max(100).catch(25),
  cursor: z.string().optional(),
});

export const searchParamsSortSchema = z.object({
  sort: z.string().max(40).optional(),
  dir: z.enum(["asc", "desc"]).catch("desc"),
});

export function toOffset(page: number, perPage: number): number {
  return (page - 1) * perPage;
}

export type SearchParamsPagination = z.infer<
  typeof searchParamsPaginationSchema
>;
export type SearchParamsSort = z.infer<typeof searchParamsSortSchema>;
"use client";

/**
 * Page-number state synced to the query string.
 */
import { useCallback, useMemo } from "react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { DEFAULT_PAGE_SIZE } from "@/config/constants";
import { pageCount as computePageCount } from "@/lib/pagination";

export function usePagination(
  total: number,
  perPage: number = DEFAULT_PAGE_SIZE,
): {
  page: number;
  perPage: number;
  pageCount: number;
  setPage: (page: number) => void;
} {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const pageCount = useMemo(
    () => computePageCount(total, perPage),
    [total, perPage],
  );

  const page = useMemo(() => {
    const raw = Number.parseInt(searchParams.get("page") ?? "1", 10);
    if (!Number.isFinite(raw) || raw < 1) return 1;
    return pageCount > 0 ? Math.min(raw, pageCount) : 1;
  }, [searchParams, pageCount]);

  const setPage = useCallback(
    (next: number) => {
      const params = new URLSearchParams(searchParams.toString());
      if (next <= 1) {
        params.delete("page");
      } else {
        params.set("page", String(next));
      }
      const query = params.toString();
      router.replace(query.length > 0 ? `${pathname}?${query}` : pathname, {
        scroll: false,
      });
    },
    [router, pathname, searchParams],
  );

  return { page, perPage, pageCount, setPage };
}
"use client";

/**
 * Page-number pagination control.
 *
 * Owner A — design system. The windowing arithmetic lives in
 * `./_lib/pagination-range` so it can be unit-tested without a DOM; this file
 * is the markup around it. `usePagination` in the hooks layer owns the state.
 */
import type { ReactElement } from "react";
import { cn } from "@/lib/cn";
import {
  buildPageRange,
  pageCount,
  rangeEnd,
  rangeStart,
} from "./_lib/pagination-range";
import { FOCUS_RING } from "./_lib/tokens";

export type PaginationProps = { page: number; perPage: number; total: number; onPageChange: (page: number) => void };

export function Pagination(props: PaginationProps): ReactElement | null {
  const { page, perPage, total, onPageChange } = props;

  const pages = pageCount(total, perPage);
  // One page of results needs no control at all — the summary line alone is
  // noise on a list that cannot be paged.
  if (pages <= 1) return null;

  const current = Math.min(Math.max(1, page), pages);
  const tokens = buildPageRange(current, pages);

  const go = (target: number) => {
    const next = Math.min(Math.max(1, target), pages);
    if (next !== current) onPageChange(next);
  };

  const stepClass = cn(
    "inline-flex h-8 items-center rounded-md border border-black/12 px-2.5 text-xs text-black/70",
    "hover:bg-surface-muted disabled:cursor-not-allowed disabled:opacity-45",
    FOCUS_RING,
  );

  return (
    <nav
      aria-label="Pagination"
      className="flex flex-wrap items-center justify-between gap-3"
    >
      <p className="text-xs text-black/55 dark:text-white/55">
        <span className="tabular-nums">{rangeStart(current, perPage, total)}</span>
        {"–"}
        <span className="tabular-nums">{rangeEnd(current, perPage, total)}</span>
        {" of "}
        <span className="tabular-nums">{total}</span>
      </p>

      <div className="flex items-center gap-1">
        <button
          type="button"
          onClick={() => go(current - 1)}
          disabled={current === 1}
          className={stepClass}
        >
          Previous
        </button>

        {tokens.map((token, index) =>
          token === "gap" ? (
            <span
              key={`gap-${index}`}
              aria-hidden="true"
              className="px-1 text-xs text-black/40"
            >
              …
            </span>
          ) : (
            <button
              key={token}
              type="button"
              aria-label={`Page ${token}`}
              aria-current={token === current ? "page" : undefined}
              onClick={() => go(token)}
              className={cn(
                "inline-flex h-8 min-w-8 items-center justify-center rounded-md px-2 text-xs tabular-nums",
                token === current
                  ? "bg-brand-500 font-medium text-white"
                  : "text-black/70 hover:bg-surface-muted dark:text-white/70",
                FOCUS_RING,
              )}
            >
              {token}
            </button>
          ),
        )}

        <button
          type="button"
          onClick={() => go(current + 1)}
          disabled={current === pages}
          className={stepClass}
        >
          Next
        </button>
      </div>
    </nav>
  );
}
